begin;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('quiz-images','quiz-images',true,10485760,array['image/png','image/jpeg','image/webp','image/gif','image/avif']) on conflict(id) do update set public=true,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
drop policy if exists dun_images_read on storage.objects;
create policy dun_images_read on storage.objects for select to authenticated using(bucket_id='quiz-images' and public.dun_active() and ((storage.foldername(name))[1]=auth.uid()::text or public.dun_admin()));
drop policy if exists dun_images_insert on storage.objects;
create policy dun_images_insert on storage.objects for insert to authenticated with check(bucket_id='quiz-images' and public.dun_active() and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists dun_images_update on storage.objects;
create policy dun_images_update on storage.objects for update to authenticated using(bucket_id='quiz-images' and public.dun_active() and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='quiz-images' and (storage.foldername(name))[1]=auth.uid()::text);
drop policy if exists dun_images_delete on storage.objects;
create policy dun_images_delete on storage.objects for delete to authenticated using(bucket_id='quiz-images' and public.dun_email() is not null and (storage.foldername(name))[1]=auth.uid()::text);
commit;
